/**
 * Sidebar configuration file.
 *
 * Items can be:
 * - "autogenerated" — auto-scan a directory (default behavior)
 * - doc references with optional overrides
 * - external links
 * - category groupings
 *
 * If this file exports an empty object or the key for a section is not found,
 * the sidebar falls back to filesystem-based auto-generation.
 */

import type { SidebarDefinition, SidebarsConfig } from "@takazudo/zudo-doc/sidebar-utils";
export type { SidebarLink, SidebarDoc, SidebarCategory, SidebarAutogenerated, SidebarItem, SidebarDefinition, SidebarsConfig } from "@takazudo/zudo-doc/sidebar-utils";

/**
 * Sidebar configuration.
 * Keys correspond to headerNav categoryMatch values.
 * If a section has no config here, it uses auto-generated filesystem sidebar.
 */
// Each header section is its own broadening ceiling. Nested branch focus still
// climbs inside that section. Omitted entries, including Assets, stay editorial.
const section = (): SidebarDefinition => ({ items: [], scopeRoot: "configured" });
const sidebars: SidebarsConfig = {
  "getting-started": section(),
  // Hub for the Learn dropdown: its landing page plus each child section's overview.
  learn: { items: ["learn", "guides", "components", "markdown-features"], scopeRoot: "configured" },
  guides: section(),
  components: section(),
  "markdown-features": section(),
  reference: section(),
  develop: section(),
  changelog: section(),
  blog: section(),
  claude: section(),
  codex: section(),
};

export default sidebars;
